#include "test_assertions.h"
#include <cstdlib>
#include <fstream>
#include <sstream>
#include <string>
#include <vector>
#include "rss/RssParser.h"
#include "rss/TextUtils.h"
#include "storage/CacheCodec.h"
#include "network/HttpRange.h"
#include "timeline/TimelineParser.h"
#include "audio/RecoveryPolicy.h"

using namespace gpp;
void setUp(){}
void tearDown(){}

static std::string fixture(const char* name){std::ifstream f(std::string("tests/gcores/fixtures/")+name);std::ostringstream s;s<<f.rdbuf();return s.str();}
void test_time_strings(){uint32_t s=0;TEST_ASSERT_TRUE(TimelineParser::parseTime("02:35",s));TEST_ASSERT_EQUAL_UINT32(155,s);TEST_ASSERT_TRUE(TimelineParser::parseTime("1:05:20",s));TEST_ASSERT_EQUAL_UINT32(3920,s);TEST_ASSERT_FALSE(TimelineParser::parseTime("1:99",s));TEST_ASSERT_FALSE(TimelineParser::parseTime("999999999999999:00",s));TEST_ASSERT_FALSE(TimelineParser::parseTime("1193047:59:59",s));}
void test_entities_and_html(){auto s=text::collapseWhitespace(text::stripHtml("甲&amp;乙<br>第二行&nbsp;&#x4E2D;"));TEST_ASSERT_EQUAL_STRING("甲&乙\n第二行 中",s.c_str());}
void test_timeline_variants(){auto v=TimelineParser::parseText("- 时间轴 -<br> 02：35 - 第一节<br>00:00\t开场<br>1:05:20 — 结尾<br>9:00:00 错误",4000);TEST_ASSERT_EQUAL_UINT32(3,v.size());TEST_ASSERT_EQUAL_UINT32(0,v[0].startSeconds);TEST_ASSERT_EQUAL_STRING("第一节",v[1].title.c_str());}
void test_no_timeline(){TEST_ASSERT_TRUE(TimelineParser::parseText("普通节目简介，没有节点",3600).empty());}
void test_chapters_json(){auto v=TimelineParser::parsePodcastChaptersJson(R"({"chapters":[{"startTime":0,"title":"开场 {说明}"},{"startTime":90.5,"title":"话题"}]})",200);TEST_ASSERT_EQUAL_UINT32(2,v.size());TEST_ASSERT_EQUAL_UINT32(90,v[1].startSeconds);TEST_ASSERT_EQUAL_STRING("开场 {说明}",v[0].title.c_str());}
void test_timeline_pack_roundtrip(){auto source=TimelineParser::parseText("00:00 开场<br>02:35 第一节<br>1:05:20 结尾",5000);const std::string packed=TimelineParser::pack(source);std::vector<TimelineEntry> decoded;TEST_ASSERT_TRUE(TimelineParser::unpack(packed,decoded));TEST_ASSERT_EQUAL_UINT32(source.size(),decoded.size());TEST_ASSERT_EQUAL_UINT32(155,decoded[1].startSeconds);TEST_ASSERT_EQUAL_STRING("第一节",decoded[1].title.c_str());std::string corrupt=packed;corrupt.pop_back();TEST_ASSERT_FALSE(TimelineParser::unpack(corrupt,decoded));}
void test_all_feed_fixtures(){const char* names[]={"games.xml","life.xml","pro.xml","heshi.xml","yinping.xml"};const char* titles[]={"机核游戏频道","机核生活频道","机核兴趣频道","核市奇谭","银屏系漫游指南"};for(int i=0;i<5;++i){auto r=RssParser::parseDocument(fixture(names[i]),10,31);TEST_ASSERT_TRUE_MESSAGE(r.ok,names[i]);TEST_ASSERT_EQUAL_STRING(titles[i],r.channelTitle.c_str());TEST_ASSERT_EQUAL_UINT32(1,r.episodes.size());TEST_ASSERT_FALSE(r.episodes[0].title.empty());TEST_ASSERT_FALSE(r.episodes[0].enclosureUrl.empty());TEST_ASSERT_GREATER_THAN_UINT32(0,r.episodes[0].durationSeconds);}}
void test_missing_fields(){auto r=RssParser::parseDocument("<rss><channel><title>X</title><item><title>仅标题</title></item></channel></rss>",10,5);TEST_ASSERT_TRUE(r.ok);TEST_ASSERT_EQUAL_STRING("仅标题",r.episodes[0].title.c_str());TEST_ASSERT_TRUE(r.episodes[0].enclosureUrl.empty());}
void test_long_title_is_bounded(){std::string title(900,'a');auto r=RssParser::parseDocument("<rss><channel><title>X</title><item><title>"+title+"</title><enclosure url=\"x.mp3\"/></item></channel></rss>");TEST_ASSERT_LESS_OR_EQUAL_UINT32(384,r.episodes[0].title.size());}
void test_stream_parser_stops_at_limit(){RssParser p(2);const std::string xml="<rss><channel><title>X</title><item><title>A</title></item><item><title>B</title></item><item><title>C</title></item></channel></rss>";for(size_t i=0;i<xml.size()&&!p.complete();i+=7)p.feed(xml.data()+i,std::min<size_t>(7,xml.size()-i));TEST_ASSERT_TRUE(p.complete());TEST_ASSERT_EQUAL_UINT32(2,p.episodeCount());auto r=p.finish();TEST_ASSERT_EQUAL_UINT32(2,r.episodes.size());TEST_ASSERT_EQUAL_STRING("B",r.episodes[1].title.c_str());}
void test_lean_episode_storage(){std::string rows;for(int i=0;i<120;++i)rows+="<br>"+std::to_string(i)+":00 章节"+std::to_string(i);std::string xml="<rss><channel><title>X</title><item><title>长节目</title><description><![CDATA[很长的简介"+std::string(5000,'a')+rows+"]]></description><itunes:duration>2:30:00</itunes:duration><enclosure url=\"x.mp3\"/></item></channel></rss>";auto r=RssParser::parseDocument(xml);TEST_ASSERT_TRUE(r.ok);const auto&e=r.episodes[0];TEST_ASSERT_LESS_OR_EQUAL_UINT32(384,e.description.size());TEST_ASSERT_TRUE(e.contentEncoded.empty());TEST_ASSERT_TRUE(e.timeline.empty());TEST_ASSERT_FALSE(e.timelinePacked.empty());std::vector<TimelineEntry> unpacked;TEST_ASSERT_TRUE(TimelineParser::unpack(e.timelinePacked,unpacked));TEST_ASSERT_EQUAL_UINT32(80,unpacked.size());for(const auto&t:unpacked)TEST_ASSERT_TRUE(t.raw.empty());}
void test_optional_live_feed_files(){const char*dir=std::getenv("GPP_LIVE_FIXTURE_DIR");if(!dir||!*dir)return;const char*names[]={"games.xml","life.xml","pro.xml","heshi.xml","yinping.xml"};for(const char*name:names){std::ifstream f(std::string(dir)+"/"+name,std::ios::binary);TEST_ASSERT_TRUE_MESSAGE(static_cast<bool>(f),name);std::ostringstream s;s<<f.rdbuf();auto r=RssParser::parseDocument(s.str(),5,257);TEST_ASSERT_TRUE_MESSAGE(r.ok,name);TEST_ASSERT_EQUAL_UINT32_MESSAGE(5,r.episodes.size(),name);for(const auto&e:r.episodes){TEST_ASSERT_FALSE_MESSAGE(e.title.empty(),name);TEST_ASSERT_FALSE_MESSAGE(e.enclosureUrl.empty(),name);TEST_ASSERT_GREATER_THAN_UINT32_MESSAGE(0,e.durationSeconds,name);TEST_ASSERT_LESS_OR_EQUAL_UINT32_MESSAGE(384,e.description.size(),name);TEST_ASSERT_TRUE_MESSAGE(e.contentEncoded.empty(),name);TEST_ASSERT_TRUE_MESSAGE(e.timeline.empty(),name);}if(std::string(name)!="games.xml"){std::vector<TimelineEntry> timeline;TEST_ASSERT_TRUE(TimelineParser::unpack(r.episodes[0].timelinePacked,timeline));TEST_ASSERT_GREATER_THAN_UINT32_MESSAGE(0,timeline.size(),name);TEST_ASSERT_TRUE(timeline[0].raw.empty());}const std::string cache=CacheCodec::encodeEpisodes(r.episodes);TEST_ASSERT_EQUAL_UINT32(CacheCodec::encodedSize(r.episodes),cache.size());TEST_ASSERT_LESS_THAN_UINT32_MESSAGE(96*1024,cache.size(),name);}}
void test_cache_roundtrip(){auto r=RssParser::parseDocument(fixture("games.xml"));std::string bytes=CacheCodec::encodeEpisodes(r.episodes);std::vector<PodcastEpisode> decoded;TEST_ASSERT_TRUE(CacheCodec::decodeEpisodes(bytes,decoded));TEST_ASSERT_EQUAL_STRING(r.episodes[0].guid.c_str(),decoded[0].guid.c_str());TEST_ASSERT_EQUAL_UINT32(r.episodes[0].timelinePacked.size(),decoded[0].timelinePacked.size());bytes[0]='X';TEST_ASSERT_FALSE(CacheCodec::decodeEpisodes(bytes,decoded));}
void test_cache_corruption_is_bounded(){auto r=RssParser::parseDocument(fixture("games.xml"));const std::string valid=CacheCodec::encodeEpisodes(r.episodes);std::vector<PodcastEpisode> decoded;std::string truncated=valid;truncated.pop_back();TEST_ASSERT_FALSE(CacheCodec::decodeEpisodes(truncated,decoded));std::string trailing=valid;trailing.push_back('x');TEST_ASSERT_FALSE(CacheCodec::decodeEpisodes(trailing,decoded));std::string excessiveCount=valid;excessiveCount[5]=static_cast<char>(0xff);excessiveCount[6]=static_cast<char>(0xff);excessiveCount[7]=static_cast<char>(0xff);excessiveCount[8]=static_cast<char>(0x7f);TEST_ASSERT_FALSE(CacheCodec::decodeEpisodes(excessiveCount,decoded,20));}
void test_http_content_range(){auto r=parseHttpContentRange("bytes 1024-2047/4096");TEST_ASSERT_TRUE(r.valid);TEST_ASSERT_FALSE(r.unsatisfied);TEST_ASSERT_TRUE(r.totalKnown);TEST_ASSERT_EQUAL_UINT64(1024,r.start);TEST_ASSERT_EQUAL_UINT64(2047,r.end);TEST_ASSERT_EQUAL_UINT64(4096,r.total);r=parseHttpContentRange(" bytes */4096 ");TEST_ASSERT_TRUE(r.valid);TEST_ASSERT_TRUE(r.unsatisfied);TEST_ASSERT_EQUAL_UINT64(4096,r.total);TEST_ASSERT_FALSE(parseHttpContentRange("bytes 100-99/1000").valid);TEST_ASSERT_FALSE(parseHttpContentRange("bytes 100-100/100").valid);TEST_ASSERT_FALSE(parseHttpContentRange("items 0-1/2").valid);TEST_ASSERT_FALSE(parseHttpContentRange("bytes 18446744073709551616-2/3").valid);}
void test_audio_recovery_policy(){using D=RecoveryDecision;TEST_ASSERT_EQUAL_INT(static_cast<int>(D::None),static_cast<int>(RecoveryPolicy::decide(false,true,true,RecoveryPolicy::kNetworkStallMs-1,UINT32_MAX,0)));TEST_ASSERT_EQUAL_INT(static_cast<int>(D::Retry),static_cast<int>(RecoveryPolicy::decide(false,true,true,RecoveryPolicy::kNetworkStallMs,UINT32_MAX,0)));TEST_ASSERT_EQUAL_INT(static_cast<int>(D::WaitForNetwork),static_cast<int>(RecoveryPolicy::decide(false,false,false,RecoveryPolicy::kStoppedDecoderMs,UINT32_MAX,0)));TEST_ASSERT_EQUAL_INT(static_cast<int>(D::None),static_cast<int>(RecoveryPolicy::decide(false,true,false,RecoveryPolicy::kStoppedDecoderMs,RecoveryPolicy::kRetryGapMs-1,1)));TEST_ASSERT_EQUAL_INT(static_cast<int>(D::Retry),static_cast<int>(RecoveryPolicy::decide(false,true,false,RecoveryPolicy::kStoppedDecoderMs,RecoveryPolicy::kRetryGapMs,1)));TEST_ASSERT_EQUAL_INT(static_cast<int>(D::GiveUp),static_cast<int>(RecoveryPolicy::decide(false,true,true,RecoveryPolicy::kNetworkStallMs,RecoveryPolicy::kRetryGapMs,RecoveryPolicy::kMaxAttempts)));TEST_ASSERT_EQUAL_INT(static_cast<int>(D::Retry),static_cast<int>(RecoveryPolicy::decide(true,false,true,RecoveryPolicy::kLocalStallMs,UINT32_MAX,0)));}

int main(int,char**){UNITY_BEGIN();RUN_TEST(test_time_strings);RUN_TEST(test_entities_and_html);RUN_TEST(test_timeline_variants);RUN_TEST(test_no_timeline);RUN_TEST(test_chapters_json);RUN_TEST(test_timeline_pack_roundtrip);RUN_TEST(test_all_feed_fixtures);RUN_TEST(test_missing_fields);RUN_TEST(test_long_title_is_bounded);RUN_TEST(test_stream_parser_stops_at_limit);RUN_TEST(test_lean_episode_storage);RUN_TEST(test_optional_live_feed_files);RUN_TEST(test_cache_roundtrip);RUN_TEST(test_cache_corruption_is_bounded);RUN_TEST(test_http_content_range);RUN_TEST(test_audio_recovery_policy);return UNITY_END();}
